import base64
import json
from typing import Any, Dict, Optional

import boto3


def normalize_expense_fields(document_bytes: bytes, mime_type: str = "application/pdf") -> Dict[str, Any]:
    """
    Normalize extracted expense fields into a standard JSON schema using Amazon Textract AnalyzeExpense.

    Standard schema:
    {
        "merchant_name": str | None,
        "total_amount": str | None,
        "currency": str | None,
        "transaction_date": str | None,
        "invoice_receipt_id": str | None,
        "tax_amount": str | None,
        "tip_amount": str | None,
        "subtotal": str | None,
        "payment_method": str | None,
        "items": [
            {
                "description": str | None,
                "quantity": str | None,
                "unit_price": str | None,
                "amount": str | None
            }, ...
        ],
        "raw_provider_response": dict
    }
    """
    client = boto3.client("textract")

    response = client.analyze_expense(
        Document={"Bytes": document_bytes},
    )

    def _field_value(expense_field: Dict[str, Any]) -> Optional[str]:
        if not expense_field:
            return None
        for key in ("ValueDetection", "LabelDetection"):
            if key in expense_field and expense_field[key]:
                text = expense_field[key].get("Text")
                if text is not None:
                    return text
        return expense_field.get("Text")

    def _normalize_currency(field: Dict[str, Any]) -> Optional[str]:
        if not field:
            return None
        currency = field.get("Currency")
        if isinstance(currency, dict):
            return currency.get("Code") or currency.get("CurrencyCode")
        return None

    def _collect_summary(fields: list) -> Dict[str, Optional[str]]:
        summary: Dict[str, Optional[str]] = {
            "merchant_name": None,
            "total_amount": None,
            "currency": None,
            "transaction_date": None,
            "invoice_receipt_id": None,
            "tax_amount": None,
            "tip_amount": None,
            "subtotal": None,
            "payment_method": None,
        }

        for field in fields:
            ft = field.get("Type", {}).get("Text")
            value = _field_value(field)
            currency = _normalize_currency(field)

            if ft == "VENDOR_NAME" and not summary["merchant_name"]:
                summary["merchant_name"] = value
            elif ft in ("TOTAL", "AMOUNT_DUE") and not summary["total_amount"]:
                summary["total_amount"] = value
                summary["currency"] = summary["currency"] or currency
            elif ft in ("INVOICE_RECEIPT_DATE", "TRANSACTION_DATE", "PAYMENT_DATE") and not summary["transaction_date"]:
                summary["transaction_date"] = value
            elif ft in ("INVOICE_RECEIPT_ID", "RECEIPT_NUMBER", "INVOICE_ID") and not summary["invoice_receipt_id"]:
                summary["invoice_receipt_id"] = value
            elif ft in ("TAX", "TAX_AMOUNT") and not summary["tax_amount"]:
                summary["tax_amount"] = value
                summary["currency"] = summary["currency"] or currency
            elif ft in ("TIP", "TIP_AMOUNT") and not summary["tip_amount"]:
                summary["tip_amount"] = value
                summary["currency"] = summary["currency"] or currency
            elif ft in ("SUBTOTAL", "NET_AMOUNT") and not summary["subtotal"]:
                summary["subtotal"] = value
                summary["currency"] = summary["currency"] or currency
            elif ft in ("PAYMENT_METHOD", "CREDIT_CARD", "DEBIT_CARD", "CASH") and not summary["payment_method"]:
                summary["payment_method"] = value or ft

        return summary

    def _collect_items(line_items: list) -> list:
        items = []
        for group in line_items:
            line_item_fields = group.get("LineItemExpenseFields", [])
            item = {
                "description": None,
                "quantity": None,
                "unit_price": None,
                "amount": None,
            }
            for field in line_item_fields:
                ft = field.get("Type", {}).get("Text")
                value = _field_value(field)
                if ft in ("ITEM", "DESCRIPTION", "PRODUCT_CODE"):
                    item["description"] = value or item["description"]
                elif ft == "QUANTITY":
                    item["quantity"] = value or item["quantity"]
                elif ft in ("PRICE", "UNIT_PRICE"):
                    item["unit_price"] = value or item["unit_price"]
                elif ft in ("LINE_ITEM_AMOUNT", "AMOUNT"):
                    item["amount"] = value or item["amount"]
            if any(v is not None for v in item.values()):
                items.append(item)
        return items

    expense_documents = response.get("ExpenseDocuments", [])
    summary_fields = []
    line_items = []

    for doc in expense_documents:
        summary_fields.extend(doc.get("SummaryFields", []))
        line_items.extend(doc.get("LineItemGroups", []))

    normalized = _collect_summary(summary_fields)
    normalized["items"] = _collect_items(line_items)
    normalized["raw_provider_response"] = response

    return normalized


def normalize_expense_fields_from_file(path: str, mime_type: str = "application/pdf") -> Dict[str, Any]:
    with open(path, "rb") as f:
        return normalize_expense_fields(f.read(), mime_type=mime_type)
